[CmdletBinding()]param([string]$DatabaseUser=$(if($env:POSTGRES_USER){$env:POSTGRES_USER}else{'dip'}),[string]$DatabaseHost=$(if($env:POSTGRES_HOST){$env:POSTGRES_HOST}else{'127.0.0.1'}),[int]$DatabasePort=$(if($env:POSTGRES_PORT){[int]$env:POSTGRES_PORT}else{5432}),[string]$DatabasePassword=$(if($env:POSTGRES_PASSWORD){$env:POSTGRES_PASSWORD}else{''}))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;foreach($n in 'dotnet','psql'){if(-not(Get-Command $n -ErrorAction SilentlyContinue)){throw "$n is required."}}
$root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$db='dip_migration_'+[guid]::NewGuid().ToString('N').Substring(0,12);$env:PGPASSWORD=$DatabasePassword;$old=$env:ConnectionStrings__PostgreSql
try{
 & psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -v ON_ERROR_STOP=1 -c "CREATE DATABASE \"$db\" OWNER \"$DatabaseUser\";" *> $null;if($LASTEXITCODE-ne0){throw 'Temporary migration database creation failed.'}
 $env:ConnectionStrings__PostgreSql="Host=$DatabaseHost;Port=$DatabasePort;Database=$db;Username=$DatabaseUser;Password=$DatabasePassword"
 Push-Location $root;try{& dotnet tool restore;if($LASTEXITCODE-ne0){throw 'dotnet tool restore failed.'};$migrations=@(& dotnet ef migrations list --project src/Dip.Infrastructure --startup-project src/Dip.Api --no-connect 2>$null)|Where-Object{$_ -match '^\d{8,}_.+'};if($migrations.Count-lt1){throw 'No EF migrations were discovered.'};$latest=$migrations[-1];if($migrations.Count-gt1){$previous=$migrations[-2];& dotnet ef database update $previous --project src/Dip.Infrastructure --startup-project src/Dip.Api;if($LASTEXITCODE-ne0){throw "Migration to previous revision failed: $previous"}};& dotnet ef database update $latest --project src/Dip.Infrastructure --startup-project src/Dip.Api;if($LASTEXITCODE-ne0){throw "Migration to latest revision failed: $latest"};& dotnet ef database update $latest --project src/Dip.Infrastructure --startup-project src/Dip.Api;if($LASTEXITCODE-ne0){throw 'Idempotent migration reapply failed.'};$applied=(& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d $db -At -c 'SELECT count(*) FROM "__EFMigrationsHistory";'|Out-String).Trim();if($applied-notmatch'^\d+$'-or[int]$applied-lt1){throw 'Migration history verification failed.'};Write-Host "Database migration verification PASS: $latest ($applied applied)" -ForegroundColor Green}finally{Pop-Location}
}finally{$env:ConnectionStrings__PostgreSql=$old;& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -c "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='$db';" *> $null;& psql -h $DatabaseHost -p $DatabasePort -U $DatabaseUser -d postgres -c "DROP DATABASE IF EXISTS \"$db\";" *> $null}
